def main():
    root = pathlib.Path(__file__).resolve().parent.parent
    page = root / 'voprosy.html'
    src = page.read_text(encoding='utf-8')
    out, n = [], 0
    for gid, title, qs in G:
        items = []
        for q, a in qs:
            n += 1
            items.append(f'<details id="q{n}"><summary>{html.escape(q)}</summary><div>{a}</div></details>')
        out.append(f'<section class="vq-group" id="{gid}" aria-labelledby="{gid}-h"><h2 id="{gid}-h">{html.escape(title)}</h2>'
                   f'<div class="vq-acc">\n' + '\n'.join(items) + '\n</div></section>')
        src = re.sub(rf'(href="#{gid}"[^>]*>[^<]*<i>)\d*(</i>)', rf'\g<1>{len(qs)}\g<2>', src)
    src = re.sub(r'(<!-- faq:start -->).*?(<!-- faq:end -->)', lambda m: m.group(1) + '\n' + '\n'.join(out) + '\n' + m.group(2), src, flags=re.S)
    src = re.sub(r'data-total="\d*"', f'data-total="{n}"', src)
    page.write_text(src, encoding='utf-8')
    print(n, 'вопросов')


if __name__ == '__main__':
    main()
